buildGradleAdditions.insert:
repositories {
    google()
    mavenCentral()
}
dependencies {
    implementation('com.google.ads.mediation:unity') {
        version {
            strictly '4.19.0.0'
        }
    }
    implementation('com.unity3d.ads:unity-ads') {
        version {
            strictly '4.19.0'
        }
    }
}

gameActivityClassAdditions.insert:
/** Updates Unity privacy values individually so omitted signals leave the SDK untouched. */
public boolean AndroidThunkJava_ApplyOpenMobileAdsAdMobUnityConsentSignals(
    final boolean applyGdpr,
    final boolean hasUserConsent,
    final boolean applyUsPrivacy,
    final boolean doNotSell,
    final boolean applyNonBehavioral,
    final boolean nonBehavioral
)
{
    try
    {
        if (applyGdpr)
        {
            com.unity3d.ads.UnityAds.setUserConsent(hasUserConsent);
            if (!java.lang.Boolean.valueOf(hasUserConsent).equals(
                com.unity3d.ads.UnityAds.getUserConsent()))
            {
                return false;
            }
        }
        if (applyUsPrivacy)
        {
            com.unity3d.ads.UnityAds.setUserOptOut(doNotSell);
            if (!java.lang.Boolean.valueOf(doNotSell).equals(
                com.unity3d.ads.UnityAds.getUserOptOut()))
            {
                return false;
            }
        }
        if (applyNonBehavioral)
        {
            com.unity3d.ads.UnityAds.setNonBehavioral(nonBehavioral);
            if (!java.lang.Boolean.valueOf(nonBehavioral).equals(
                com.unity3d.ads.UnityAds.getNonBehavioral()))
            {
                return false;
            }
        }
        return true;
    }
    catch (Exception exception)
    {
        return false;
    }
}
